Time Complexity: O(n) We traverse both strings once, and all hash map operations (insert and lookup) take constant time on average.Auxiliary Space: O(1)  Since the strings contain only lowercase English letters, the maximum size of each hash map is bounded by 26, making it constant space.[Expected Approach 2] Fixed-Size Array Mapping Approach - O(n) Time and O(1) SpaceWe avoid language-specific hash overhead by using fixed-size arrays, leveraging the 26-letter lowercase alphabet. Each character is mapped to an index ('a' -> 0, ..., 'z' -> 25) for constant-time access. One array stores the character mappings, while another tracks if a character in the second string is already used — ensuring a one-to-one correspondence.
            C++

    #include <iostream>
#include <vector>
#include <string>
using namespace std;

bool areIsomorphic(string &s1, string &s2) {
    int n = s1.size();

    // marked[v] is true if character 
    // 'a'+v from s2 is already used
    vector<bool> marked(26, false);

    // map[u] stores the character index
    // in s2 that s1's 'a'+u maps to
    vector<int> map(26, -1);

    for (int i = 0; i < n; i++) {
        int u = s1[i] - 'a';
        int v = s2[i] - 'a';

        // If s1[i] has not been mapped yet
        if (map[u] == -1) {

            // If s2[i] is already used
            // by another character
            if (marked[v]) return false;

            // Assign mapping and mark s2[i] as used
            map[u] = v;
            marked[v] = true;
        }
        // If already mapped, check for consistency
        else if (map[u] != v) {
            return false;
        }
    }

    return true;
}

int main() {
    string s1 = "aab";
    string s2 = "xxy";

    cout << (areIsomorphic(s1, s2) ? "true\n" : "false\n");
    return 0;
}


